private String name;
private int wins;
private int losses;

public FootballTeam(String name, int wins, int losses) {
  this.name = name; this.wins = wins; this.losses = losses;
}

public FootballTeam(String name) {
  this.name = name; this.wins = 0; this.losses = 0;
}

public String getName() { return name; }
public int getWins() { return wins; }
public int getLosses() { return losses; }

public boolean hasGoodRecord() {
  return wins > losses;
}

public static void main(String[] args) {
  FootballTeam t = new FootballTeam("AITI", 3, 5);
  System.out.println(t.hasGoodRecord());   // false
  t.addWin(); t.addWin(); t.addWin();      // wins = 6
  System.out.println(t.hasGoodRecord());   // true
}
